import sys

def solve():
    input_data = sys.stdin.read().splitlines()
    idx = 0
    if idx < len(input_data):
        t_line = input_data[idx].strip()
        idx += 1
        if not t_line:
            while idx < len(input_data) and not input_data[idx].strip():
                idx += 1
            if idx < len(input_data):
                t_line = input_data[idx].strip()
                idx += 1
        T = int(t_line)
    else:
        return

    for _ in range(T):
        teams = {}
        for _ in range(12):
            while idx < len(input_data) and not input_data[idx].rstrip('\n'):
                idx += 1
            if idx >= len(input_data):
                break
            line = input_data[idx].strip()
            idx += 1

            parts = line.split(' vs. ')
            home_part = parts[0].split()
            away_part = parts[1].split()

            home_name = home_part[0]
            home_goals = int(home_part[1])
            away_goals = int(away_part[0])
            away_name = away_part[1]

            if home_name not in teams:
                teams[home_name] = {'points': 0, 'gd': 0}
            if away_name not in teams:
                teams[away_name] = {'points': 0, 'gd': 0}

            teams[home_name]['gd'] += home_goals - away_goals
            teams[away_name]['gd'] += away_goals - home_goals

            if home_goals > away_goals:
                teams[home_name]['points'] += 3
            elif away_goals > home_goals:
                teams[away_name]['points'] += 3
            else:
                teams[home_name]['points'] += 1
                teams[away_name]['points'] += 1

        team_list = list(teams.items())
        team_list.sort(key=lambda x: (-x[1]['points'], -x[1]['gd']))

        top_team = team_list[0][0]
        second_team = team_list[1][0]

        print(f"{top_team} {second_team}")

if __name__ == "__main__":
    solve()
